@st.cache_data(ttl=90, show_spinner=False)
def history(symbol, period, interval, auto_adjust=False):
    symbol = _clean_text(symbol, upper=True)
    if not symbol:
        return None

    try:
        df = yf.Ticker(symbol).history(
            period=period,
            interval=interval,
            auto_adjust=auto_adjust,
            prepost=False
        )
        if df is not None and not df.empty:
            df = df.dropna(subset=["Open","High","Low","Close"])
            if not df.empty:
                return df
    except Exception:
        pass

    try:
        raw = yf.download(
            tickers=symbol,
            period=period,
            interval=interval,
            auto_adjust=auto_adjust,
            progress=False,
            threads=False,
            prepost=False
        )
        if raw is None or raw.empty:
            return None

        df = raw.copy()
        if isinstance(df.columns, pd.MultiIndex):
            # Common single-ticker yfinance layout: (Price, Ticker)
            if symbol in df.columns.get_level_values(-1):
                try:
                    df = df.xs(symbol, axis=1, level=-1, drop_level=True)
                except Exception:
                    pass
            elif symbol in df.columns.get_level_values(0):
                try:
                    df = df.xs(symbol, axis=1, level=0, drop_level=True)
                except Exception:
                    pass

        if isinstance(df.columns, pd.MultiIndex):
            df.columns = df.columns.get_level_values(0)

        needed = ["Open","High","Low","Close"]
        if all(c in df.columns for c in needed):
            df = df.dropna(subset=needed)
            return None if df.empty else df
    except Exception:
        pass

    return None


@st.cache_data(ttl=900, show_spinner=False)
def info(symbol):
    try: return yf.Ticker(symbol).info or {}
    except Exception: return {}

@st.cache_data(ttl=15, show_spinner=False)
def live_quote(symbol):
    try:
        t = yf.Ticker(symbol); fi = getattr(t,"fast_info",None); price=None; currency=""
        if fi:
            try: price = fi.get("last_price")
            except Exception: pass
            try: currency = fi.get("currency") or ""
            except Exception: pass
        inf = info(symbol)
        if price is None:
            h = t.history(period="1d",interval="1m",auto_adjust=False)
            if h is not None and not h.empty: price=float(h["Close"].dropna().iloc[-1])
        return {"price": float(price) if price is not None else None, "currency":currency or inf.get("currency","") or "", "name":inf.get("longName") or inf.get("shortName") or symbol}
    except Exception:
        return {"price":None,"currency":"","name":symbol}




def vf_quote_freshness(created_at, current_price, reference_price=None):
    """
    Compare the alert snapshot with the current quote.
    Does not claim broker-tick equivalence: Yahoo/yfinance is an independent
    market data source and may differ in timestamp/venue from the broker.
    """
    now = pd.Timestamp.now(tz="UTC")
    created = pd.to_datetime(created_at, errors="coerce", utc=True)

    age_min = np.nan
    if pd.notna(created):
        try:
            age_min = max((now - created).total_seconds() / 60.0, 0.0)
        except Exception:
            pass

    current = _vf_num(current_price)
    ref = _vf_num(reference_price)
    deviation = np.nan
    if pd.notna(current) and pd.notna(ref) and ref != 0:
        deviation = (current / ref - 1.0) * 100.0

    # Freshness concerns the alert age; integrity concerns current divergence.
    if pd.isna(current):
        state, kind = "COURS INDISPONIBLE", "muted"
    elif pd.notna(age_min) and age_min <= 2:
        state, kind = "TRÈS FRAIS", "green"
    elif pd.notna(age_min) and age_min <= 10:
        state, kind = "À JOUR", "blue"
    elif pd.notna(age_min) and age_min <= 30:
        state, kind = "À REVÉRIFIER", "amber"
    else:
        state, kind = "ALERTE ANCIENNE", "amber"

    return {
        "age_min": age_min,
        "deviation_pct": deviation,
        "state": state,
        "kind": kind,
    }


def vf_live_alert_validation(row):
    if hasattr(row, "to_dict"):
        row = row.to_dict()
    row = dict(row or {})

    symbol = _clean_text(row.get("symbol"), upper=True)
    q = live_quote(symbol) if symbol else {"price": None}
    current = _vf_num(q.get("price"))

    # Prefer the alert's stored market/entry reference.
    reference = _vf_num(row.get("price"))
    if pd.isna(reference):
        reference = _vf_num(row.get("entry"))

    freshness = vf_quote_freshness(
        row.get("created_at"),
        current,
        reference_price=reference
    )

    entry = _vf_num(row.get("entry"))
    stop = _vf_num(row.get("stop"))
    tp1 = _vf_num(row.get("tp1"))
    tp2 = _vf_num(row.get("tp2"))

    decision = "VALIDE À REVÉRIFIER"
    decision_kind = "blue"
    reason = "Le setup est comparé au dernier cours disponible."

    if pd.isna(current):
        decision = "DONNÉE LIVE INDISPONIBLE"
        decision_kind = "muted"
        reason = "Impossible de valider le setup sans cours récent."
    elif pd.notna(stop) and current <= stop:
        decision = "SETUP INVALIDÉ"
        decision_kind = "red"
        reason = "Le dernier cours disponible est au niveau ou sous le Stop."
    elif pd.notna(tp2) and current >= tp2:
        decision = "TP2 DÉJÀ DÉPASSÉ"
        decision_kind = "green"
        reason = "L'objectif TP2 a déjà été atteint/dépassé : l'ancienne entrée n'est plus actuelle."
    elif pd.notna(tp1) and current >= tp1:
        decision = "TP1 DÉJÀ DÉPASSÉ"
        decision_kind = "amber"
        reason = "TP1 a déjà été atteint/dépassé : revalider le R/R avant toute entrée."
    elif pd.notna(entry):
        dist_entry = abs(current - entry) / entry * 100 if entry else np.nan
        if pd.notna(dist_entry) and dist_entry > 3.0:
            decision = "PRIX TROP ÉLOIGNÉ"
            decision_kind = "amber"
            reason = f"Le cours s'est écarté de {dist_entry:.1f}% de l'entrée calculée."
        elif pd.notna(dist_entry) and dist_entry <= 1.0:
            decision = "ZONE D'ENTRÉE COHÉRENTE"
            decision_kind = "green"
            reason = "Le cours reste proche de la zone d'entrée calculée."
        else:
            decision = "REVALIDATION NÉCESSAIRE"
            decision_kind = "blue"
            reason = "Le cours a évolué depuis la création de l'alerte."

    return {
        **freshness,
        "current_price": current,
        "reference_price": reference,
        "decision": decision,
        "decision_kind": decision_kind,
        "reason": reason,
        "currency": _clean_text(q.get("currency")),
    }


def vf_alert_live_strip(row):
    live = vf_live_alert_validation(row)

    c1,c2,c3,c4 = st.columns(4)
    current = live.get("current_price")
    age = live.get("age_min")
    dev = live.get("deviation_pct")

    c1.metric("Cours actuel", f"{current:.2f}" if pd.notna(current) else "—")
    c2.metric(
        "Âge alerte",
        f"{age:.0f} min" if pd.notna(age) else "—"
    )
    c3.metric(
        "Écart alerte → live",
        f"{dev:+.2f}%" if pd.notna(dev) else "—"
    )
    c4.markdown(
        vf_board_badge(live.get("decision","À vérifier"), live.get("decision_kind","muted")),
        unsafe_allow_html=True
    )

    reason = _clean_text(live.get("reason"))
    if reason:
        st.caption(reason)

    return live



@st.cache_data(ttl=120, show_spinner=False)
def batch_history(symbols, period="6mo", interval="1d"):
    symbols = [str(x).strip().upper() for x in symbols if str(x).strip()]
    if not symbols:
        return {}
    try:
        raw = yf.download(
            tickers=" ".join(symbols), period=period, interval=interval,
            group_by="ticker", auto_adjust=False, threads=True,
            progress=False, prepost=False,
        )
    except Exception:
        return {}
    out = {}
    if raw is None or raw.empty:
        return out
    if len(symbols) == 1:
        one = raw.copy()
        if isinstance(one.columns, pd.MultiIndex):
            one.columns = one.columns.get_level_values(-1)
        req = [c for c in ["Open","High","Low","Close","Volume"] if c in one.columns]
        if all(c in one.columns for c in ["Open","High","Low","Close"]):
            out[symbols[0]] = one.dropna(subset=["Open","High","Low","Close"])
        return out
    for sym in symbols:
        try:
            if isinstance(raw.columns, pd.MultiIndex):
                lvl0 = raw.columns.get_level_values(0)
                lvl1 = raw.columns.get_level_values(1)
                if sym in lvl0:
                    d = raw[sym].copy()
                elif sym in lvl1:
                    d = raw.xs(sym, axis=1, level=1).copy()
                else:
                    continue
            else:
                continue
            if all(c in d.columns for c in ["Open","High","Low","Close"]):
                out[sym] = d.dropna(subset=["Open","High","Low","Close"])
        except Exception:
            continue
    return out


def fast_scan(symbols, min_upside=3.0, min_rr=2.0, min_score=72, top_n=20):
    # Stage 1: one threaded/batched daily download for the whole universe.
    daily = batch_history(symbols, period="6mo", interval="1d")
    candidates = []
    for sym, df in daily.items():
        setup = trade_setup(df)
        if not setup:
            continue
        if setup["upside"] >= min_upside and setup["rr"] >= min_rr and setup["score"] >= min_score:
            candidates.append({"Ticker": sym, **setup})
    candidates = sorted(candidates, key=lambda r: (r["score"], r["rr"], r["upside"]), reverse=True)[:max(top_n, 1)]
    if not candidates:
        return pd.DataFrame()

    # Stage 2: confirm only the finalists on 1h. One more batch call, not N calls.
    finalists = [r["Ticker"] for r in candidates]
    hourly = batch_history(finalists, period="3mo", interval="1h")
    rows = []
    for r in candidates:
        sym = r["Ticker"]
        conf = trade_setup(hourly.get(sym)) if sym in hourly else None
        conf_score = conf["score"] if conf else np.nan
        trend_ok = bool(conf and conf["score"] >= 65 and conf["rr"] >= 1.5)
        combined = round((0.65 * r["score"] + 0.35 * conf_score), 1) if conf else float(r["score"])
        rows.append({
            "Ticker": sym,
            "Score": r["score"],
            "Confirmation 1h": conf_score,
            "Score combiné": combined,
            "Prix": r["price"],
            "Entrée": r["entry"],
            "Stop": r["stop"],
            "TP1": r["tp1"],
            "TP2": r["tp2"],
            "Potentiel %": r["upside"],
            "R/R": r["rr"],
            "Qualité": r["quality"],
            "Confirmé 1h": "✅" if trend_ok else "⚠️",
            "Raisons": " • ".join(r.get("reasons", [])),
        })
    out = pd.DataFrame(rows)
    if not out.empty:
        out = out.sort_values(["Score combiné","R/R","Potentiel %"], ascending=False)
    return out



