def vf_alert_chip(alert_type):
    t = _clean_text(alert_type, upper=True)
    if t == "ENTRY":
        cls = "vf-chip-entry"
    elif t in {"EXIT", "TAKE_PROFIT"}:
        cls = "vf-chip-exit"
    elif t in {"RISK","PROTECT","INVALIDATED","NEWS_RISK"}:
        cls = "vf-chip-risk"
    else:
        cls = "vf-chip-info"
    return f'<span class="vf-chip {cls}">{t or "ALERTE"}</span>'



